UPDATE TB_PRODUCT SET
    PRODUCT_CD = #{productCd}, PRODUCT_KIND = #{productKind}, SUB_TYPE = #{subType}, PRODUCT_NM = #{productNm},
    SUMMARY = #{summary}, RATE_TEXT = #{rateText}, ICON = #{icon}, DETAIL_URL = #{detailUrl}, ON_SALE_YN = #{onSaleYn},
    HOME_DISP_YN = #{homeDispYn}, HOME_DISP_ORD = #{homeDispOrd, jdbcType=INTEGER}, UPD_AT = #{updAt}, UPD_BY = #{updBy}
WHERE PRODUCT_ID = #{productId}
